class Solution {
public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        vector<string> result;
        int n = (int)words.size();
        int i = 0;
        while (i < n) {
            int lineStart = i;
            int lineLen = (int)words[i].length();
            i++;
            while (i < n && lineLen + 1 + (int)words[i].length() <= maxWidth) {
                lineLen += 1 + (int)words[i].length();
                i++;
            }

            int wordCount = i - lineStart;
            string line;

            if (i == n) {
                // Last line: left-justified, single spaces, pad right
                for (int j = lineStart; j < i; j++) {
                    if (j > lineStart) line += ' ';
                    line += words[j];
                }
                line += string(maxWidth - (int)line.length(), ' ');
            } else if (wordCount == 1) {
                // Single word on a non-last line: left-justified
                line = words[lineStart] + string(maxWidth - (int)words[lineStart].length(), ' ');
            } else {
                // Fully justified: distribute spaces evenly, left gaps get more
                int totalChars = 0;
                for (int j = lineStart; j < i; j++) totalChars += (int)words[j].length();
                int totalSpaces = maxWidth - totalChars;
                int gaps = wordCount - 1;
                int spacePerGap = totalSpaces / gaps;
                int extra = totalSpaces % gaps;

                for (int j = lineStart; j < i; j++) {
                    line += words[j];
                    if (j < i - 1) {
                        int spaces = spacePerGap + ((j - lineStart) < extra ? 1 : 0);
                        line += string(spaces, ' ');
                    }
                }
            }
            result.push_back(line);
        }
        return result;
    }
};
